em as (select x.* from reference, jsonb_to_recordset(j->'migrations') as x(filename text,version text,sha256 text)),
er as (select x.* from reference, jsonb_to_recordset(j->'relations') as x(relation text,kind text,migration text)),
ec as (select x.* from reference, jsonb_to_recordset(j->'columns') as x(relation text,"column" text,migration text)),
ef as (select x.* from reference, jsonb_to_recordset(j->'functions') as x(signature text,name text,introduced text,migration text,body_md5 text,arg_types jsonb,history jsonb,security_definer boolean,language text)),
ep as (select x.* from reference, jsonb_to_recordset(j->'policies') as x(relation text,policy text,migration text,source_sql text,alterations jsonb)),
et as (select x.* from reference, jsonb_to_recordset(j->'triggers') as x("schema" text,relation text,"trigger" text,migration text)),
ei as (select x.* from reference, jsonb_to_recordset(j->'indexes') as x(relation text,"index" text,migration text)),
ledger_meta as (
 select pg_catalog.to_regclass('supabase_migrations.schema_migrations') as oid
),
ledger_access as (
 select oid,
 case when oid is null then false else pg_catalog.has_table_privilege(oid,'SELECT') end as readable,
 exists(select 1 from pg_catalog.pg_attribute a where a.attrelid=oid and a.attname='version' and not a.attisdropped) as has_version,
 exists(select 1 from pg_catalog.pg_attribute a where a.attrelid=oid and a.attname='name' and not a.attisdropped) as has_name
 from ledger_meta
),
ledger_xml as (
 select a.*, case when a.oid is not null and a.readable and a.has_version
 then pg_catalog.query_to_xml(
  pg_catalog.format(
   'select coalesce(jsonb_agg(jsonb_build_object(''version'',version::text,''name'',%s) order by version),''[]''::jsonb)::text as payload from supabase_migrations.schema_migrations',
   case when a.has_name then 'name::text' else 'null::text' end
  ),true,false,'')
 else '<table><row><payload>[]</payload></row></table>'::xml end as doc
 from ledger_access a
),
ledger_rows as (
 select entry->>'version' as version,entry->>'name' as name
 from ledger_xml l cross join xmltable('/table/row' passing l.doc columns payload text path 'payload') x
 cross join lateral jsonb_array_elements(x.payload::jsonb) entry
),
rr as (
 select e.relation,e.kind,e.migration,c.oid,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.reloptions,
 c.relowner,c.reltuples,c.relacl
 from er e left join pg_catalog.pg_namespace n on n.nspname='public'
 left join pg_catalog.pg_class c on c.relnamespace=n.oid and c.relname=e.relation
),
cr as (
 select e.relation,e."column",e.migration,a.attnum,a.atttypid,a.atttypmod,a.attnotnull,a.attgenerated,a.attidentity,a.attacl,r.oid,
