 from ec e left join rr r on r.relation=e.relation
 left join pg_catalog.pg_attribute a on a.attrelid=r.oid and a.attname=e."column" and a.attnum>0 and not a.attisdropped
 left join pg_catalog.pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
),
fr as (
 select e.signature,e.name,e.introduced,e.migration,e.body_md5,e.history,e.security_definer,e.language,
 p.oid,p.prosrc,p.prosecdef,p.provolatile,p.proconfig,p.proowner,p.proacl,l.lanname
 from ef e
 cross join lateral (
  select coalesce(bool_and(pg_catalog.to_regtype(t.v) is not null),true) as all_types_present,
  coalesce(string_agg(pg_catalog.to_regtype(t.v)::oid::text,' ' order by t.i),'') as argument_oids
  from jsonb_array_elements_text(e.arg_types) with ordinality t(v,i)
 ) expected_types
 left join pg_catalog.pg_namespace n on n.nspname='public'
 left join pg_catalog.pg_proc p on p.pronamespace=n.oid and p.proname=e.name
 and expected_types.all_types_present and p.proargtypes::text=expected_types.argument_oids
 left join pg_catalog.pg_language l on l.oid=p.prolang
),
pr as (
 select e.relation,e.policy,e.migration,e.source_sql,e.alterations,p.oid
 from ep e left join rr r on r.relation=e.relation
 left join pg_catalog.pg_policy p on p.polrelid=r.oid and p.polname=e.policy
),
tr as (
 select e."schema",e.relation,e."trigger",e.migration,t.oid,t.tgenabled,t.tgfoid,t.tgrelid
 from et e left join pg_catalog.pg_namespace n on n.nspname=e."schema"
 left join pg_catalog.pg_class c on c.relnamespace=n.oid and c.relname=e.relation
 left join pg_catalog.pg_trigger t on t.tgrelid=c.oid and t.tgname=e."trigger" and not t.tgisinternal
),
ir as (
 select e.relation,e."index",e.migration,i.indexrelid,i.indisvalid,i.indisready
