),
actual_columns as (
 select r.relation,r.oid,a.attnum,a.attname,a.atttypid,a.atttypmod,a.attnotnull,a.attacl
 from rr r join pg_catalog.pg_attribute a on a.attrelid=r.oid and a.attnum>0 and not a.attisdropped
),
view_whitelists as (
 select * from (values
 ('public_paid_projects',array['id','company_id','title','description','requirements','skills','deadline','budget_units','status','created_at']::text[]),
 ('public_paid_milestones',array['id','project_id','position','title','deliverables','deadline','amount_units']::text[]),
 ('public_credential_events',array['credential_id','event_type','reason','created_at']::text[])
 ) v(relation,columns)
)
select jsonb_build_object(
 '01_context',jsonb_build_object(
  'expected_project_reference','wizlluiyhsxtsxpuwudc',
  'project_confirmation','Confirm SQL Editor project manually; current_database alone does not identify a Supabase project.',
  'checked_at_utc',to_char(current_timestamp at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'database',current_database(),'sql_role',current_user,
  'postgres_version',current_setting('server_version'),
  'scope','Catalogs and migration version/name only. No user records or workflow RPCs. No writes.',
  'warnings','Ledger/presence are not migration completion. Review body hashes, policy expressions, grants, defaults and constraints; absence/drift never authorizes a rerun.'),
 '02_migration_ledger',jsonb_build_object(
  'table_exists',(select oid is not null from ledger_access),
  'readable',(select readable from ledger_access),'has_version_column',(select has_version from ledger_access),
  'has_name_column',(select has_name from ledger_access),
  'entries',coalesce((select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from ledger_rows),'[]'::jsonb)),
 '03_per_migration_markers',coalesce((
  select jsonb_agg(jsonb_build_object('filename',m.filename,'source_sha256',m.sha256,
   'ledger_version_present',case when (select readable and has_version from ledger_access) then exists(select 1 from ledger_rows l where l.version=m.version) else null end,
   'missing_markers',coalesce((select jsonb_agg(jsonb_build_object('kind',x.kind,'object',x.object) order by x.kind,x.object) from markers x where x.migration=m.filename and not x.present),'[]'::jsonb),
   'present_marker_count',(select count(*) from markers x where x.migration=m.filename and x.present),
   'defined_or_replaced_functions',coalesce((select jsonb_agg(f.signature order by f.signature) from fr f where exists(select 1 from jsonb_array_elements(f.history) h where h->>'migration'=m.filename)),'[]'::jsonb),
   'verdict','UNVERIFIED: inspect full metadata. Later migrations legitimately replace earlier bodies/policies. Do not rerun based on this row.') order by m.filename) from em m),'[]'::jsonb),
 '04_relations',coalesce((
  select jsonb_agg(jsonb_build_object('relation',r.relation,'introduced',r.migration,'expected_kind',r.kind,
  'exists',r.oid is not null,'actual_kind',r.relkind,'owner',pg_catalog.pg_get_userbyid(r.relowner),
  'rls_enabled',r.relrowsecurity,'rls_forced',r.relforcerowsecurity,'options',r.reloptions,
  'estimated_rows_not_an_exact_count',r.reltuples,
  'view_definition',case when r.relkind='v' then pg_catalog.pg_get_viewdef(r.oid,true) else null end) order by r.relation) from rr r),'[]'::jsonb),
 '05_required_columns',coalesce((
  select jsonb_agg(jsonb_build_object('relation',c.relation,'column',c."column",'introduced',c.migration,
  'exists',c.attnum is not null,'actual_type',pg_catalog.format_type(c.atttypid,c.atttypmod),
  'not_null',c.attnotnull,'default',c.default_expression,'generated',c.attgenerated,'identity',c.attidentity) order by c.relation,c."column") from cr c),'[]'::jsonb),
 '06_all_actual_columns',coalesce((
  select jsonb_agg(jsonb_build_object('relation',a.relation,'column',a.attname,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),
   'not_null',a.attnotnull,'known_source_column',exists(select 1 from ec e where e.relation=a.relation and e."column"=a.attname)) order by a.relation,a.attnum) from actual_columns a),'[]'::jsonb),
 '07_functions',coalesce((
  select jsonb_agg(jsonb_build_object('signature',f.signature,'introduced',f.introduced,'latest_source',f.migration,
  'exists',f.oid is not null,'owner',pg_catalog.pg_get_userbyid(f.proowner),
  'result_type',case when f.oid is not null then pg_catalog.pg_get_function_result(f.oid) end,
  'security_definer',f.prosecdef,'expected_security_definer',f.security_definer,
  'language',f.lanname,'expected_language',f.language,'volatility',f.provolatile,'settings_including_search_path',f.proconfig,
  'actual_body_md5',md5(f.prosrc),'expected_latest_body_md5',f.body_md5,
  'body_matches_latest_source',case when f.oid is null then null else md5(f.prosrc)=f.body_md5 end,
  'matching_source_versions',coalesce((select jsonb_agg(h->>'migration') from jsonb_array_elements(f.history) h where h->>'body_md5'=md5(f.prosrc)),'[]'::jsonb),
  'client_execute',coalesce((select jsonb_object_agg(c.rolname,pg_catalog.has_function_privilege(c.oid,f.oid,'EXECUTE')) from client_roles c where f.oid is not null),'{}'::jsonb),
  'acl',case when f.oid is null then null else to_jsonb(coalesce(f.proacl,pg_catalog.acldefault('f',f.proowner))) end) order by f.signature) from fr f),'[]'::jsonb),
 '08_actual_policies',coalesce((
  select jsonb_agg(jsonb_build_object('relation',p.tablename,'policy',p.policyname,'permissive',p.permissive,
  'roles',p.roles,'command',p.cmd,'using',p.qual,'with_check',p.with_check,
  'known_source_name',exists(select 1 from ep e where e.relation=p.tablename and e.policy=p.policyname)) order by p.tablename,p.policyname)
  from pg_catalog.pg_policies p where p.schemaname='public' and exists(select 1 from er e where e.relation=p.tablename)),'[]'::jsonb),
 '09_expected_policy_reference',coalesce((
  select jsonb_agg(jsonb_build_object('relation',p.relation,'policy',p.policy,'exists',p.oid is not null,
  'source_migration',p.migration,'creation_reference_only',p.source_sql,'later_alterations',p.alterations) order by p.relation,p.policy) from pr p),'[]'::jsonb),
 '10_table_and_column_privileges',jsonb_build_object(
  'table_acl',coalesce((select jsonb_agg(jsonb_build_object('relation',r.relation,'acl',to_jsonb(coalesce(r.relacl,pg_catalog.acldefault('r',r.relowner)))) order by r.relation) from rr r where r.oid is not null),'[]'::jsonb),
  'explicit_column_acl',coalesce((select jsonb_agg(jsonb_build_object('relation',a.relation,'column',a.attname,'acl',to_jsonb(a.attacl)) order by a.relation,a.attnum) from actual_columns a where a.attacl is not null),'[]'::jsonb),
  'effective_table_access',coalesce((select jsonb_agg(jsonb_build_object('role',c.rolname,'relation',r.relation,
   'select',pg_catalog.has_table_privilege(c.oid,r.oid,'SELECT'),'insert',pg_catalog.has_table_privilege(c.oid,r.oid,'INSERT'),
   'update',pg_catalog.has_table_privilege(c.oid,r.oid,'UPDATE'),'delete',pg_catalog.has_table_privilege(c.oid,r.oid,'DELETE')) order by c.rolname,r.relation) from rr r cross join client_roles c where r.oid is not null),'[]'::jsonb),
  'effective_column_select',coalesce((select jsonb_agg(jsonb_build_object('role',c.rolname,'relation',a.relation,'column',a.attname,
   'select',pg_catalog.has_column_privilege(c.oid,a.oid,a.attnum,'SELECT')) order by c.rolname,a.relation,a.attnum) from actual_columns a cross join client_roles c),'[]'::jsonb)),
 '11_triggers',coalesce((
  select jsonb_agg(jsonb_build_object('schema',t."schema",'relation',t.relation,'trigger',t."trigger",'source',t.migration,
  'exists',t.oid is not null,'enabled',t.tgenabled,
  'definition',case when t.oid is not null then pg_catalog.pg_get_triggerdef(t.oid,true) end) order by t."schema",t.relation,t."trigger") from tr t),'[]'::jsonb),
 '12_constraints_and_indexes',jsonb_build_object(
  'constraints',coalesce((select jsonb_agg(jsonb_build_object('relation',r.relation,'name',c.conname,'type',c.contype,'validated',c.convalidated,
   'definition',pg_catalog.pg_get_constraintdef(c.oid,true)) order by r.relation,c.conname) from rr r join pg_catalog.pg_constraint c on c.conrelid=r.oid),'[]'::jsonb),
  'all_indexes',coalesce((select jsonb_agg(jsonb_build_object('relation',r.relation,'definition',pg_catalog.pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready) order by r.relation,i.indexrelid) from rr r join pg_catalog.pg_index i on i.indrelid=r.oid),'[]'::jsonb),
  'expected_named_indexes',coalesce((select jsonb_agg(jsonb_build_object('relation',i.relation,'index',i."index",'source',i.migration,'exists',i.indexrelid is not null,'valid',i.indisvalid,'ready',i.indisready) order by i.relation,i."index") from ir i),'[]'::jsonb)),
 '13_public_projection_safety',coalesce((
  select jsonb_agg(jsonb_build_object('relation',v.relation,'allowed_columns',v.columns,
   'unexpected_columns',coalesce((select jsonb_agg(a.attname) from actual_columns a where a.relation=v.relation and not(a.attname=any(v.columns))),'[]'::jsonb),
   'missing_allowed_columns',coalesce((select jsonb_agg(x) from unnest(v.columns) x where not exists(select 1 from actual_columns a where a.relation=v.relation and a.attname=x)),'[]'::jsonb)) order by v.relation) from view_whitelists v),'[]'::jsonb),
 '14_roles_extensions_default_acl',jsonb_build_object(
  'client_roles',coalesce((select jsonb_agg(jsonb_build_object('role',rolname,'inherits',rolinherit,'bypass_rls',rolbypassrls,'superuser',rolsuper) order by rolname) from client_roles),'[]'::jsonb),
  'role_memberships',coalesce((select jsonb_agg(jsonb_build_object('member',m.rolname,'inherits_role',r.rolname,'admin_option',a.admin_option) order by m.rolname,r.rolname) from pg_catalog.pg_auth_members a join pg_catalog.pg_roles m on m.oid=a.member join pg_catalog.pg_roles r on r.oid=a.roleid),'[]'::jsonb),
  'extensions',coalesce((select jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname) order by e.extname) from pg_catalog.pg_extension e join pg_catalog.pg_namespace n on n.oid=e.extnamespace),'[]'::jsonb),
  'default_acls',coalesce((select jsonb_agg(jsonb_build_object('owner',pg_catalog.pg_get_userbyid(d.defaclrole),'schema',n.nspname,'object_type',d.defaclobjtype,'acl',to_jsonb(d.defaclacl)) order by d.defaclrole,d.defaclobjtype) from pg_catalog.pg_default_acl d left join pg_catalog.pg_namespace n on n.oid=d.defaclnamespace where d.defaclnamespace=0 or n.nspname='public'),'[]'::jsonb)),
 '15_unexpected_triggers_or_overloads',jsonb_build_object(
  'triggers',coalesce((select jsonb_agg(jsonb_build_object('relation',r.relation,'trigger',t.tgname,'enabled',t.tgenabled,'definition',pg_catalog.pg_get_triggerdef(t.oid,true))) from rr r join pg_catalog.pg_trigger t on t.tgrelid=r.oid and not t.tgisinternal where not exists(select 1 from tr e where e.oid=t.oid)),'[]'::jsonb),
  'function_overloads',coalesce((select jsonb_agg(jsonb_build_object('name',p.proname,'identity_arguments',pg_catalog.pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'body_md5',md5(p.prosrc),'acl',to_jsonb(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))))) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and exists(select 1 from ef e where e.name=p.proname) and not exists(select 1 from fr e where e.oid=p.oid)),'[]'::jsonb))
,
 '16_additional_public_objects',jsonb_build_object(
  'relations',coalesce((select jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'owner',pg_catalog.pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'options',c.reloptions,
   'acl',to_jsonb(coalesce(c.relacl,pg_catalog.acldefault('r',c.relowner))),
   'view_definition_md5',case when c.relkind='v' then md5(pg_catalog.pg_get_viewdef(c.oid,true)) end) order by c.relname)
   from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p','v','m') and not exists(select 1 from er e where e.relation=c.relname)),'[]'::jsonb),
  'functions',coalesce((select jsonb_agg(jsonb_build_object('name',p.proname,'identity_arguments',pg_catalog.pg_get_function_identity_arguments(p.oid),'owner',pg_catalog.pg_get_userbyid(p.proowner),
   'security_definer',p.prosecdef,'settings',p.proconfig,'body_md5',md5(p.prosrc),
   'extension_owned',exists(select 1 from pg_catalog.pg_depend d where d.classid='pg_catalog.pg_proc'::regclass and d.objid=p.oid and d.deptype='e'),
   'acl',to_jsonb(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner)))) order by p.proname,p.oid)
   from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and not exists(select 1 from ef e where e.name=p.proname)),'[]'::jsonb),
  'public_schema_access',coalesce((select jsonb_agg(jsonb_build_object('role',c.rolname,'usage',pg_catalog.has_schema_privilege(c.oid,n.oid,'USAGE'),'create',pg_catalog.has_schema_privilege(c.oid,n.oid,'CREATE'))) from pg_catalog.pg_namespace n cross join client_roles c where n.nspname='public'),'[]'::jsonb)),
 '17_auth_catalog_presence_only',jsonb_build_object('users_exists',pg_catalog.to_regclass('auth.users') is not null,'identities_exists',pg_catalog.to_regclass('auth.identities') is not null)
) as proofpak_read_only_diagnostic;
